"""Compact MAGICO controls, using durable server progress rather than animation."""
PANEL = r'''
<section class="panel" id="magicPanel"><div class="row"><h2>✦ MAGICO</h2><span class="badge">IBRIDO ECONOMICO</span></div>
<p class="muted">Prepara CUT, parole chiave e coperture verificate in una revisione separata. Le immagini alternative restano disattivate. APPLICA resta manuale nel bridge.</p>
<details><summary>Opzioni e budget</summary><div class="row magicOptions">
<label>Pause <select id="magicPause"><option value="soft">Soft</option><option value="medium" selected>Medium</option><option value="strong">Strong</option></select></label>
<label>Chiamate AI massime <input id="magicCloud" type="number" min="1" max="100" value="20"></label>
<label>Di cui visive <input id="magicVisual" type="number" min="0" max="100" value="4"></label>
<label><input type="checkbox" id="magicPexels" checked> Pexels</label><label><input type="checkbox" id="magicShorts" checked> YouTube Shorts</label><label><input type="checkbox" id="magicImages" checked> Immagini</label>
</div><small class="muted">Nessun credito Codex nel programma. Le API configurate possono avere costi o limiti propri; i risultati salvati vengono riutilizzati.</small></details>
<div class="row magicActions"><button id="magicStart" class="primary" disabled>✦ AVVIA MAGICO</button><button id="magicCancel" hidden>ANNULLA</button><button id="magicResume" hidden>RIPRENDI</button><button id="magicRestart" hidden title="Crea una nuova esecuzione e conserva i risultati precedenti">RIPARTI DA ZERO</button><button id="magicRetrySelection" hidden>RIPROVA COPERTURE</button><button id="cutAutoCoverage" type="button" hidden disabled>AGGIORNA AUTO-COPERTURE</button><button id="magicOpenResult" hidden>APRI RISULTATO MODIFICABILE</button></div>
<div id="magicAutoCoverageBox" hidden role="status"><strong id="magicAutoCoverageStatus"></strong><progress id="magicAutoCoverageProgress" max="100" value="0"></progress><small id="magicAutoCoverageDetail"></small></div>
<div id="magicStatus" role="status" aria-live="polite">Carica un video o usa il bridge.</div><progress id="magicProgress" max="100" value="0"></progress>
<small id="magicUsage" class="muted"></small><div id="magicPhases" class="magicPhases" aria-label="Fasi MAGICO"></div><ul id="magicWarnings"></ul><details><summary>Diagnostica MAGICO</summary><button id="magicCopyDebug">COPIA DEBUG</button><pre id="magicDebug"></pre></details></section>
'''
CSS = r'''<style>#magicPanel{border-color:#7873b1}#magicPanel h2{margin:0}#magicPanel progress{display:block;width:100%;height:10px;margin:12px 0;accent-color:var(--lime)}.magicActions{margin:16px 0}.magicOptions{padding:12px 0;gap:16px}.magicOptions label{font-size:12px}.magicOptions input[type=number]{width:72px}#magicWarnings{font-size:12px;line-height:1.6;max-height:180px;overflow:auto}#magicDebug{max-height:220px;overflow:auto;white-space:pre-wrap}#magicStatus{font-weight:700;font-size:13px}.magicPhases{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0 4px}.magicPhase{display:inline-flex;align-items:center;gap:5px;padding:4px 8px;border:1px solid var(--line,#555879);border-radius:999px;color:var(--muted,#b8bdd1);font-size:10px;font-weight:800}.magicPhase.done{border-color:#39784b;background:#13271a;color:#86e89f}.magicPhase.active{border-color:#806a2d;background:#2b2513;color:#ffd166}.magicPhase.pending{opacity:.72}</style>'''
CSS += '<style>.magicOptions select,.magicOptions input[type=number]{background:var(--panel,#242640);color:var(--ink,#f0f1ff);border:1px solid var(--line,#555879);border-radius:8px;padding:7px 9px}</style>'
JS = r'''
let magicRow=null,magicPolling=false,magicPid=null,magicBusy=false;
const MAGIC_PHASES=[['cut','CUT'],['editorial','PIANO'],['research','RICERCA'],['selection','COPERTURE'],['preparation','PACCHETTO'],['delivery','BRIDGE']];
function renderMagicPhases(r){const root=$('magicPhases');if(!root)return;root.replaceChildren();if(!r?.run_id)return;const phase=String(r.phase||'').toLowerCase(),running=['queued','running'].includes(r.status);for(const [key,label] of MAGIC_PHASES){const done=!!r.checkpoints?.[key],active=!done&&running&&(phase.includes(key)||(key==='selection'&&phase.includes('cover'))||(key==='preparation'&&phase.includes('prepare'))||(key==='delivery'&&phase.includes('deliver')));const chip=document.createElement('span');chip.className=`magicPhase ${done?'done':active?'active':'pending'}`;chip.textContent=`${done?'✓':active?'●':'○'} ${label}`;root.append(chip)}}
function drawMagic(){const r=magicRow||{},busy=magicBusy||['queued','running'].includes(r.status);$('magicStart').disabled=busy||!!state.run||!state.project?.source_video;$('magicCancel').hidden=!busy;$('magicResume').hidden=!r.run_id||!['waiting_input','failed','partial','ready'].includes(r.status);$('magicResume').disabled=busy;$('magicRestart').hidden=!r.run_id||busy;$('magicRestart').disabled=busy;$('magicRetrySelection').hidden=!r.run_id||!r.checkpoints?.editorial||busy;$('magicRetrySelection').disabled=busy;$('magicOpenResult').hidden=!r.output_project_id||busy;$('magicProgress').value=Number(r.percent)||0;$('magicStatus').textContent=r.message||'Pronto · conserva il progetto attuale e crea una revisione MAGICO';const calls=Object.values(r.calls||{});$('magicUsage').textContent=r.run_id?`${r.percent||0}% · ${r.phase||''} · ${calls.filter(c=>c.cloud).length}/${r.options?.max_cloud_requests||20} chiamate AI · ${calls.filter(c=>c.cloud&&c.visual).length}/${r.options?.max_visual_requests??4} visive`:'';const warnings=$('magicWarnings');warnings.replaceChildren();for(const text of [...(r.warnings||[]),...(r.error?[r.error]:[])]){const li=document.createElement('li');li.textContent=text;for(const url of String(text).match(new RegExp('https?://[^ <>"]+', 'g'))||[]){try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))continue;const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent=' Apri fonte ↗';li.append(a)}catch(_){}}warnings.append(li)}$('magicDebug').textContent=JSON.stringify({...r,calls:calls.map(({provider,phase,visual,status,error})=>({provider,phase,visual,status,error}))},null,2);renderMagicPhases(r)}
async function openMagicOutput(focusStep=7){if(!magicRow?.output_project_id)return;const pid=magicRow.output_project_id,p=await api(`/projects/${pid}`);const cut=await api(`/projects/${pid}/cut`).catch(()=>null);const sourcePid=cut?.cut_parent_project_id||pid;const target=await api('/desktop-target').catch(()=>null);if(target?.revision)desktopTargetRevision=target.revision;const resultUrl=new URL(location.href);resultUrl.searchParams.set('project',pid);history.replaceState(null,'',resultUrl.href);show(p,p.name,`/api/curation/projects/${sourcePid}/media/source-video/source`);await hydrate();if(focusStep===7&&typeof prepareBrollViewV24==='function')prepareBrollViewV24();if(typeof openOnlyWorkflowStepV42==='function')openOnlyWorkflowStepV42(focusStep)}
async function refreshMagic(){if(magicPolling||!state.pid)return;magicPolling=true;const pid=state.pid;try{const same=magicRow&&(pid===magicRow.source_project_id||pid===magicRow.output_project_id);const row=await api(same?`/magic/${magicRow.run_id}`:`/projects/${pid}/magic/latest`);if(pid!==state.pid)return;magicPid=pid;magicRow=row.run_id?row:null;drawMagic()}catch(e){$('magicStatus').textContent=e.message}finally{magicPolling=false}}
async function ensureMagicAnalysis(pid){if(state.data?.analysis_ready)return;const started=await api(`/projects/${pid}/analyze`,{method:'POST'});if(started.status==='started'){await watch(started.run_id);for(;;){if(pid!==state.pid)throw new Error('Il progetto Source è cambiato durante l’Analysis');const response=await fetch(`/v1/debug/runs/${started.run_id}`);if(!response.ok)throw new Error('Impossibile leggere lo stato dell’Analysis automatica');const run=await response.json();$('magicStatus').textContent=`Analysis automatica · ${run.total_progress||0}% · ${run.last_message||'in corso'}`;if(['SUCCEEDED','FAILED','CANCELLED'].includes(run.status)){await hydrate();if(run.status!=='SUCCEEDED'||!state.data?.analysis_ready)throw new Error(run.last_message||'Analysis automatica non riuscita');return}await new Promise(resolve=>setTimeout(resolve,500))}}await hydrate();if(!state.data?.analysis_ready)throw new Error('Analysis automatica non pronta')}
$('magicStart').onclick=async()=>{if(magicBusy||!state.pid)return;magicBusy=true;drawMagic();const pid=state.pid;try{await ensureMagicAnalysis(pid);if(pid!==state.pid)return;const providers=[];if($('magicPexels').checked)providers.push('pexels');if($('magicShorts').checked)providers.push('youtube_shorts');if($('magicImages').checked)providers.push('google_images');const options={pause_mode:$('magicPause').value,max_cloud_requests:Number($('magicCloud').value),max_visual_requests:Number($('magicVisual').value),providers};const row=await api(`/projects/${pid}/magic`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options)});if(pid===state.pid)magicRow=row}catch(e){$('magicStatus').textContent=e.message;reportError(e)}finally{magicBusy=false;if(pid===state.pid)drawMagic()}};
$('magicCancel').onclick=async()=>{if(magicRow){magicRow=await api(`/magic/${magicRow.run_id}/cancel`,{method:'POST'});drawMagic()}};
$('magicResume').onclick=async()=>{if(!magicRow||magicBusy)return;magicBusy=true;drawMagic();try{magicRow=await api(`/magic/${magicRow.run_id}/resume`,{method:'POST'})}catch(e){reportError(e)}finally{magicBusy=false;drawMagic()}};
$('magicRestart').onclick=async()=>{if(!magicRow||magicBusy)return;magicBusy=true;drawMagic();try{magicRow=await api(`/magic/${magicRow.run_id}/restart`,{method:'POST'})}catch(e){reportError(e)}finally{magicBusy=false;drawMagic()}};
$('magicRetrySelection').onclick=async()=>{if(!magicRow||magicBusy)return;magicBusy=true;drawMagic();try{magicRow=await api(`/magic/${magicRow.run_id}/retry-selection`,{method:'POST'})}catch(e){reportError(e)}finally{magicBusy=false;drawMagic()}};
$('magicOpenResult').onclick=()=>openMagicOutput(7);
$('magicCopyDebug').onclick=()=>navigator.clipboard.writeText($('magicDebug').textContent).catch(reportError);
const magicSend=document.createElement('button');magicSend.id='magicSend';magicSend.textContent='INVIA AL BRIDGE';magicSend.hidden=true;magicSend.title='Rimanda il pacchetto salvato senza nuove analisi. APPLICA resta manuale; il CUT creerà una nuova timeline.';document.querySelector('.magicActions').append(magicSend);
magicSend.onclick=async()=>{if(!magicRow||magicBusy)return;magicBusy=true;drawMagic();try{magicRow=await api(`/magic/${magicRow.run_id}/send`,{method:'POST'})}catch(e){reportError(e)}finally{magicBusy=false;drawMagic()}};
const baseMagicDraw=drawMagic;drawMagic=function(){baseMagicDraw();magicSend.hidden=!magicRow?.checkpoints?.preparation;magicSend.disabled=magicBusy||['queued','running'].includes(magicRow?.status);const s=magicRow?.checkpoints?.selection?.result;if(s){$('magicUsage').textContent+=` · ${s.verified_videos||0} video verificati · ${s.disabled_images||0} immagini disattivate · ${s.uncovered||0} passaggi senza copertura`}};
const previousMagicShow=show;show=function(...args){const result=previousMagicShow(...args);drawMagic();refreshMagic();return result};
drawMagic();setInterval(refreshMagic,1500);
'''
